{
  "ops_version": "0.1.0",
  "problem_class": "lp",
  "sense": "min",
  "name": "microgrid_bess_6period",
  "assumptions": {
    "horizon": 6,
    "eta": 1.0,
    "CAP": 3.75,
    "PMAX": 1.35,
    "SOC0": 1.85,
    "LOAD": [3.1, 2.4, 1.6, 2.15, 2.35, 2.1],
    "PV": [0.0, 1.45, 2.55, 1.35, 0.65, 0.25],
    "PRICE": [1.15, 0.55, 0.28, 0.42, 0.95, 1.35]
  },
  "variables": [
    {"name": "s", "type": "continuous", "shape": [6], "lower": 0.0, "upper": 3.75},
    {"name": "charge", "type": "continuous", "shape": [6], "lower": 0.0, "upper": 1.35},
    {"name": "discharge", "type": "continuous", "shape": [6], "lower": 0.0, "upper": 1.35},
    {"name": "grid", "type": "continuous", "shape": [6], "lower": 0.0}
  ],
  "constraints": [
    {
      "name": "soc_dynamics",
      "type": "linear_equality",
      "for": {"t": "1..6"},
      "expr": "s[t-1] == s[t-2] + charge[t-1] - discharge[t-1]",
      "where": {"s[-1]": 1.85}
    },
    {
      "name": "balance",
      "type": "linear_equality",
      "for": {"t": "1..6"},
      "expr": "LOAD[t-1] == PV[t-1] + grid[t-1] + discharge[t-1] - charge[t-1]"
    }
  ],
  "objective": {
    "type": "linear",
    "expr": "sum(PRICE[t-1]*grid[t-1] for t in 1..6)"
  }
}

